// #6: replaces the current story, so only ask when there's actually
// something unsaved to lose (and via the app's own uiConfirm modal, not the
// browser's native confirm()). window.confirm() blocks synchronously so a
// caller could rely on this function's own return value; uiConfirm() can't
// (it just shows a modal and returns immediately), so a pending confirm
// returns false and calls opts.onLoaded once the user actually agrees -
// callers that need to run something AFTER the load (tutorial.js's
// tutShowMe) use that instead of trusting the return value alone.
function loadSampleModule(opts){
  opts = opts || {};
  const proceed=()=>{
    if(typeof pushUndo==='function') pushUndo();
    loadProject(JSON.parse(JSON.stringify(SAMPLE_MODULE)));
    if(typeof checkOpenOverlapSoon==='function') checkOpenOverlapSoon();
    if(typeof toast==='function' && !opts.silent) toast('Sample module loaded; explore the scenes, choices & variables.');
    if(opts.onLoaded) opts.onLoaded();
  };
  if(opts.silent || !_dirty){ proceed(); return true; }
  uiConfirm('Load the sample tutorial module? This replaces the current story.', proceed, { yes:'Load sample', no:'Cancel' });
  return false;
}
function sampleModuleLoaded(){
  try{ return project && project.meta && /Whistleblower/.test(project.meta.title||''); }catch(e){ return false; }
}
